import { useEffect, useState } from 'react';

export default function TaskList() {
  const [tasks, setTasks] = useState([]);
  const [width, setWidth] = useState(window.innerWidth);
  const [error, setError] = useState('');

  if (tasks.length === 0 && !error) {
    fetch('/api/tasks')
      .then(response => {
        if (!response.ok) throw new Error('Could not load tasks');
        return response.json();
      })
      .then(data => setTasks(data))
      .catch(err => setError(err.message));
  }

  useEffect(() => {
    window.addEventListener('resize', () => setWidth(window.innerWidth));
  }, []);

  function toggleTask(index) {
    tasks[index].done = !tasks[index].done;
    setTasks(tasks);
  }

  return (
    <section className={width < 600 ? 'tasks compact' : 'tasks'}>
      <h2>My tasks</h2>
      {error && <p role="alert">{error}</p>}
      <ul>{tasks.map((task, index) => (
        <li key={index}>
          <label><input type="checkbox" checked={task.done}
            onChange={() => toggleTask(index)} />{task.title}</label>
        </li>
      ))}</ul>
    </section>
  );
}

pub fn take_first_matching<'a>(
    entries: &'a mut Vec<String>,
    prefix: &str,
) -> Option<&'a str> {
    let index = entries.iter().position(|entry| entry.starts_with(prefix))?;
    let result = entries[index].as_str() as *const str;

    entries.remove(index);

    Some(unsafe { &*result })
}
